-- ORIVANA HEALTH: schema. All tables are prefixed oh_. Safe to run once on a fresh Supabase project.
create extension if not exists pgcrypto;
create table oh_roles (role text primary key, name text, description text, is_system boolean not null default false);
create table oh_role_permissions (role text not null references oh_roles(role) on delete cascade, permission text not null, primary key (role, permission));
create table oh_user_roles (user_id uuid not null references auth.users(id) on delete cascade, role text not null references oh_roles(role) on delete cascade, primary key (user_id, role));
create table oh_profiles (id uuid primary key references auth.users(id) on delete cascade, email text, full_name text, phone text, created_at timestamptz not null default now());
create table oh_site_settings (key text primary key, value jsonb, updated_at timestamptz default now());
create table oh_audit_logs (id bigserial primary key, user_id uuid, user_email text, action text not null, resource text, resource_id text, details jsonb, created_at timestamptz not null default now());
create table oh_media (id uuid primary key default gen_random_uuid(), title text, url text not null, kind text default 'image', alt text, size_bytes int, uploaded_by uuid, created_at timestamptz not null default now());
create table oh_notifications (id uuid primary key default gen_random_uuid(), kind text, title text not null, body text, link text, permission text, is_read boolean not null default false, created_at timestamptz not null default now());
create table oh_rate_limits (key text primary key, window_start timestamptz not null default now(), hits int not null default 1);
create table oh_pages (id uuid primary key default gen_random_uuid(), slug text unique not null, title text not null, body text, is_published boolean not null default true, seo_title text, seo_description text, updated_at timestamptz default now());
create table oh_navigation_items (id uuid primary key default gen_random_uuid(), location text not null default 'header', label text not null, href text not null, sort_order int not null default 0, is_visible boolean not null default true);
create table oh_forms (key text primary key, title text not null, description text, fields jsonb not null default '[]', success_message text, notify_email text, is_active boolean not null default true);
create table oh_form_submissions (id uuid primary key default gen_random_uuid(), form_key text not null, name text, email text, phone text, data jsonb not null default '{}', status text not null default 'new', notes text, user_id uuid, created_at timestamptz not null default now());
create table oh_leaders (id uuid primary key default gen_random_uuid(), name text not null, title text, relationship text, bio text, photo_url text, sort_order int not null default 0, is_published boolean not null default true);
-- Directory
create table oh_specialty_groups (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, sort_order int not null default 0, is_active boolean not null default true);
create table oh_specialties (id uuid primary key default gen_random_uuid(), group_id uuid references oh_specialty_groups(id) on delete set null, name text not null, slug text unique not null, summary text, overview text, addresses text, navigation_info text, educational_content text, photo_url text, sort_order int not null default 0, is_published boolean not null default true, seo_title text, seo_description text);
create table oh_partners (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, partner_type text not null default 'hospital', city text, state text, country text default 'India', summary text, description text, website text, email text, phone text, logo_url text, photo_url text, verification_status text not null default 'pending', is_published boolean not null default false, sort_order int not null default 0, created_at timestamptz default now());
create table oh_partner_specialties (partner_id uuid not null references oh_partners(id) on delete cascade, specialty_id uuid not null references oh_specialties(id) on delete cascade, primary key (partner_id, specialty_id));
create table oh_providers (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, designation text, partner_id uuid references oh_partners(id) on delete set null, specialty_id uuid references oh_specialties(id) on delete set null, bio text, photo_url text, verification_status text not null default 'pending', is_published boolean not null default false, sort_order int not null default 0);
-- Cases (assistance + medical tourism)
create table oh_case_statuses (key text primary key, label text not null, patient_message text, sort_order int not null default 0, is_terminal boolean not null default false, is_active boolean not null default true);
create sequence oh_case_seq start 1001; create sequence oh_donation_seq start 1001;
create table oh_cases (
  id uuid primary key default gen_random_uuid(), kind text not null check (kind in ('assistance','tourism')), case_ref text unique, access_code text not null,
  user_id uuid, applicant_name text not null, patient_name text, relationship text, patient_age int, country text, state text, city text, phone text, email text, language text,
  medical_concern text, hospital_doctor text, treatment_status text, treatment_required text, estimated_cost numeric(14,2), needs_financial boolean default false, amount_requested numeric(14,2),
  specialty text, treatment_sought text, existing_diagnosis text, preferred_destination text, additional_info text,
  consent_processing boolean not null default false, consent_public boolean not null default false, consent_comms boolean not null default false, declaration boolean not null default false,
  status text not null default 'submitted' references oh_case_statuses(key), coordinator_id uuid, coordinator_name text, internal_notes text, verified boolean not null default false,
  provider_responses text, provider_estimate text, appointment_request text, travel_notes text, accommodation_notes text, visa_checklist text, interpreter_notes text, followup_at timestamptz,
  public_state text not null default 'private' check (public_state in ('private','pending_review','approved','closed')), public_title text, public_summary text, public_requirement text, public_docs_status text, verified_goal numeric(14,2), public_slug text unique, public_approved_at timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index on oh_cases(kind, status); create index on oh_cases(public_state);
create table oh_case_documents (id uuid primary key default gen_random_uuid(), case_id uuid not null references oh_cases(id) on delete cascade, kind text, file_path text not null, file_name text, size_bytes int, uploaded_by text not null default 'patient', created_at timestamptz not null default now());
create table oh_case_messages (id uuid primary key default gen_random_uuid(), case_id uuid not null references oh_cases(id) on delete cascade, sender text not null check (sender in ('patient','staff')), body text not null, is_info_request boolean not null default false, author text, created_at timestamptz not null default now());
create table oh_case_events (id uuid primary key default gen_random_uuid(), case_id uuid not null references oh_cases(id) on delete cascade, status text, note text, visible_to_patient boolean not null default true, created_by text, created_at timestamptz not null default now());
create table oh_case_updates (id uuid primary key default gen_random_uuid(), case_id uuid not null references oh_cases(id) on delete cascade, title text not null, body text, is_published boolean not null default false, created_at timestamptz not null default now());
create table oh_tourism_services (id uuid primary key default gen_random_uuid(), name text not null, description text, sort_order int not null default 0, is_published boolean not null default true);
create table oh_journey_steps (id uuid primary key default gen_random_uuid(), title text not null, description text, sort_order int not null default 0, is_published boolean not null default true);
-- Training
create table oh_course_categories (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, description text, sort_order int not null default 0, is_active boolean not null default true);
create table oh_trainers (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, designation text, organisation text, bio text, photo_url text, is_published boolean not null default true);
create table oh_courses (id uuid primary key default gen_random_uuid(), slug text unique not null, title text not null, category_id uuid references oh_course_categories(id) on delete set null, trainer_id uuid references oh_trainers(id) on delete set null, format text not null default 'course' check (format in ('course','programme','workshop','webinar','institutional')),
  summary text, description text, level text, duration text, cover_url text, starts_at timestamptz, join_url text, certificate_enabled boolean not null default false, pass_mark int not null default 60, registration_open boolean not null default true, is_published boolean not null default false, sort_order int not null default 0, created_at timestamptz default now());
create table oh_course_modules (id uuid primary key default gen_random_uuid(), course_id uuid not null references oh_courses(id) on delete cascade, title text not null, description text, sort_order int not null default 0);
create table oh_lessons (id uuid primary key default gen_random_uuid(), course_id uuid not null references oh_courses(id) on delete cascade, module_id uuid references oh_course_modules(id) on delete set null, title text not null, lesson_type text not null default 'text' check (lesson_type in ('text','video','pdf','link')), body text, video_url text, file_url text, sort_order int not null default 0, is_published boolean not null default true);
create table oh_quiz_questions (id uuid primary key default gen_random_uuid(), course_id uuid not null references oh_courses(id) on delete cascade, question text not null, option_a text not null, option_b text not null, option_c text, option_d text, correct text not null check (correct in ('a','b','c','d')), explanation text, sort_order int not null default 0);
create table oh_enrollments (id uuid primary key default gen_random_uuid(), course_id uuid not null references oh_courses(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, status text not null default 'enrolled', progress int not null default 0, score int, passed boolean, certificate_no text unique, completed_at timestamptz, created_at timestamptz not null default now(), unique (course_id, user_id));
create table oh_lesson_progress (user_id uuid not null references auth.users(id) on delete cascade, lesson_id uuid not null references oh_lessons(id) on delete cascade, completed_at timestamptz not null default now(), primary key (user_id, lesson_id));
-- Events, community, equipment
create table oh_events (id uuid primary key default gen_random_uuid(), slug text unique not null, title text not null, kind text not null default 'awareness' check (kind in ('awareness','screening','education','volunteer','workshop','webinar','programme','campaign','training')), summary text, description text, starts_at timestamptz, location text, photo_url text, registration_open boolean not null default true, is_published boolean not null default false, created_at timestamptz default now());
create table oh_event_registrations (id uuid primary key default gen_random_uuid(), event_id uuid references oh_events(id) on delete cascade, reg_type text not null default 'attendee', name text not null, email text, phone text, notes text, created_at timestamptz not null default now());
create table oh_community_reports (id uuid primary key default gen_random_uuid(), title text not null, body text, event_id uuid references oh_events(id) on delete set null, is_published boolean not null default false, created_at timestamptz default now());
create table oh_equipment_categories (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, description text, sort_order int not null default 0, is_active boolean not null default true);
create table oh_equipment_listings (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, category_id uuid references oh_equipment_categories(id) on delete set null, supplier_id uuid references oh_partners(id) on delete set null, manufacturer text, description text, specifications text, certifications text, image_url text, availability text, contact_email text, is_verified boolean not null default false, is_published boolean not null default false, created_at timestamptz default now());
create table oh_equipment_services (id uuid primary key default gen_random_uuid(), name text not null, description text, sort_order int not null default 0, is_published boolean not null default true);
create table oh_navigator_options (id uuid primary key default gen_random_uuid(), label text not null, description text, href text not null, sort_order int not null default 0, is_active boolean not null default true);
-- Donations
create table oh_donations (id uuid primary key default gen_random_uuid(), donation_ref text unique, receipt_code text, user_id uuid, fund text not null default 'general' check (fund in ('case','general','community')), case_id uuid references oh_cases(id) on delete set null,
  amount numeric(14,2) not null check (amount > 0), currency text not null default 'INR', donor_name text, donor_email text, donor_phone text, is_anonymous boolean not null default false, message text,
  status text not null default 'intent' check (status in ('intent','pending','paid','failed','refunded','cancelled')), source text not null default 'online' check (source in ('online','offline')),
  provider text, provider_order_id text, provider_payment_id text, refund_amount numeric(14,2) not null default 0, refund_note text, reconciled boolean not null default false, reconciled_at timestamptz, reconciled_by text,
  acknowledged_at timestamptz, ack_note text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index on oh_donations(case_id, status);
create table oh_payment_events (id bigserial primary key, provider text not null, event_id text not null, payload jsonb, created_at timestamptz not null default now(), unique (provider, event_id));
create table oh_faqs (id uuid primary key default gen_random_uuid(), question text not null, answer text not null, topic text default 'general', sort_order int not null default 0, is_published boolean not null default true);
